export type ParsedRefundExpiredInstruction<
  TProgram extends string = typeof ARENACHAIN_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    arenaMatch: TAccountMetas[0];
    mint: TAccountMetas[1];
    vault: TAccountMetas[2];
    playerAToken: TAccountMetas[3];
    playerBToken: TAccountMetas[4];
    /** owner: player A could reassign their wallet to another program to block settlement. */
    playerA: TAccountMetas[5];
    tokenProgram: TAccountMetas[6];
  };
  data: RefundExpiredInstructionData;
};

export function parseRefundExpiredInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRefundExpiredInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      arenaMatch: getNextAccount(),
      mint: getNextAccount(),
      vault: getNextAccount(),
      playerAToken: getNextAccount(),
      playerBToken: getNextAccount(),
      playerA: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getRefundExpiredInstructionDataDecoder().decode(instruction.data),
  };
}
